#!/usr/bin/env python3
"""Generate the self-contained static Modernized Ministry site from editable page content."""
from pathlib import Path
from html import escape
ROOT = Path(__file__).resolve().parents[1]
DOMAIN = 'https://modernizedministry.com'
NAV=[('About','/'),('Flagship Demo','/flagship/'),('Solutions','/solutions/'),('Outreach','/outreach/'),('Our Work','/work/'),('Packages','/packages/')]

def logo(prefix):
    return f'''<a class="logo" href="{prefix}" aria-label="Modernized Ministry home"><svg class="logo-icon" viewBox="0 0 44 47" fill="none" aria-hidden="true"><path d="M3 39 14 8l8 18 8-18 11 31" stroke="#F1D6B4" stroke-width="4"/><path d="M12 39 22 18 32 39" stroke="#F1D6B4" stroke-width="3"/></svg><span class="logo-name">MODERNIZED<br>MINISTRY</span></a>'''

def make_links(prefix,current):
    return ''.join(f'<a href="{prefix+path.lstrip("/")}" {"aria-current=page" if path==current else ""}>{label}</a>' for label,path in NAV)

def header(prefix,current):
    return f'''<header class="site-header" id="siteHeader">{logo(prefix)}<nav class="nav" aria-label="Main navigation">{make_links(prefix,current)}</nav><a class="button small nav-button" href="{prefix}contact/">LET'S TALK <span class="arrow">↗</span></a><button class="menu-button" id="menuToggle" aria-controls="mobileMenu" aria-expanded="false" aria-label="Open menu" type="button">☰</button></header><nav class="mobile-menu" id="mobileMenu" aria-label="Mobile navigation">{make_links(prefix,current)}<a href="{prefix}contact/">Start a conversation ↗</a></nav>'''

def footer(prefix):
    return f'''<footer class="footer"><div class="shell"><div class="footer-top"><div>{logo(prefix)}<p class="footer-tagline">A timeless message.<br><em>A greater reach.</em></p><span class="eyebrow">Church outreach, thoughtfully modernized.</span></div><div class="footer-col"><small>Explore</small><a href="{prefix}">About Us</a><a href="{prefix}flagship/">Flagship Church Demo</a><a href="{prefix}work/">Design Concepts</a><a href="{prefix}solutions/">Our Solutions</a><a href="{prefix}outreach/">Guest Journey</a></div><div class="footer-col"><small>Get Started</small><a href="{prefix}packages/">Website Packages</a><a href="{prefix}process/">How We Work</a><a href="{prefix}contact/">Request a Consultation</a><a href="mailto:hello@modernizedministry.com">hello@modernizedministry.com</a><a href="{prefix}privacy/">Privacy</a></div></div><div class="footer-bottom"><span>© <span data-year>2026</span> Modernized Ministry · Made for the mission.</span><span>Built to make the next hello easier.</span></div></div></footer>'''

def cta(prefix):
    return f'''<section class="cta-photo"><div class="shell reveal"><span class="eyebrow">READY FOR WHAT'S NEXT?</span><h2>Let's reach<br><em>more people.</em></h2><p>Tell us about your church. We'll show you what a modern digital front door could look like.</p><a class="button" href="{prefix}contact/">START THE CONVERSATION <span class="arrow">↗</span></a></div></section>'''

def hero(prefix,breadcrumb,title,description,photo='worship.webp'):
    return f'''<section class="page-hero image" style="--hero-image:url('{prefix}assets/{photo}')"><div class="shell"><span class="crumb"><a href="{prefix}">Modernized Ministry</a> / {escape(breadcrumb)}</span><span class="eyebrow">CHURCH OUTREACH SOLUTIONS</span><h1 class="display">{title}</h1><p class="lead">{description}</p></div></section>'''

def page(path,title,description,body, current, demo=False):
    prefix='../' if path else ''
    actual=ROOT/path/'index.html' if path else ROOT/'index.html'
    canonical=DOMAIN+ ('/'+path+'/' if path else '/')
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#081217"><meta name="description" content="{escape(description,quote=True)}"><link rel="canonical" href="{canonical}"><link rel="icon" href="{prefix}assets/favicon.svg" type="image/svg+xml"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="{prefix}assets/site.css"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title.replace('<br>',' ').replace('<em>','').replace('</em>',''),quote=True)} — Modernized Ministry"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{DOMAIN}/assets/social-preview.jpg"><title>{escape(title.replace('<br>',' ').replace('<em>','').replace('</em>',''))} | Modernized Ministry</title></head><body class="{'demo-body' if demo else ''}">{body}<script src="{prefix}assets/site.js" defer></script></body></html>'''
    actual.parent.mkdir(parents=True,exist_ok=True)
    actual.write_text(html,encoding='utf-8')
    print(actual.relative_to(ROOT),len(html))

